def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full-width and full-height separator lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != 0]
    sep_color = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    tiles = [
        [(row_bounds[i] + 1, row_bounds[i + 1],
          col_bounds[j] + 1, col_bounds[j + 1])
         for j in range(len(col_bounds) - 1)]
        for i in range(len(row_bounds) - 1)
    ]

    # The nonempty tile outside the first column contains the template.
    template = None
    for i in range(len(tiles)):
        for j in range(1, len(tiles[i])):
            r0, r1, c0, c1 = tiles[i][j]
            points = [(r - r0, c - c0)
                      for r in range(r0, r1) for c in range(c0, c1)
                      if grid[r][c] not in (0, sep_color)]
            if points:
                template = (r1 - r0, c1 - c0, points)
                break
        if template:
            break

    th, tw, points = template
    out = [[0] * w for _ in range(h)]

    # Preserve the grid's separator lines.
    for r in sep_rows:
        for c in range(w):
            out[r][c] = sep_color
    for c in sep_cols:
        for r in range(h):
            out[r][c] = sep_color

    # Use the color in each tile of the first column for its whole tile row.
    for i, tile_row in enumerate(tiles):
        r0, r1, c0, c1 = tile_row[0]
        counts = {}
        for r in range(r0, r1):
            for c in range(c0, c1):
                color = grid[r][c]
                if color not in (0, sep_color):
                    counts[color] = counts.get(color, 0) + 1
        color = max(counts, key=counts.get)

        for tr0, tr1, tc0, tc1 in tile_row:
            for dr, dc in points:
                out[tr0 + dr][tc0 + dc] = color

    return out
